// SPDX-License-Identifier: AGPL-3.0-only
// Generates the list of the design tokens a server theme may override (ADR-0059) from src/theme.css and
// src/tokens.ts, for the Go domain that validates and renders themes and for the client's theme editor:
//
//   bun run scripts/theme-tokens.ts           write the generated files (`make web-tokens-gen`)
//
// check-tokens.ts (`make web-tokens`) fails when a committed file differs from what this generates.
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { toHex } from "../src/color";
import { fixedTokens, minimumContrast, themeColorPairs, type TokenKind, tokenRules } from "../src/tokens";
import { colorResolver, readTheme, readThemeDeclarations } from "./theme-source";

const root = resolve(import.meta.dir, "../../..");
const goPath = resolve(root, "internal/domain/instance/theme_tokens.gen.go");
const tsPath = resolve(import.meta.dir, "../src/themeTokens.gen.ts");

/** An overridable token, as both generated files list it. */
type Token = {
  name: string;
  kind: TokenKind;
  /** The default of a non-color token, as theme.css writes it. */
  value?: string;
  /** The default of a color token in each theme, as `#rrggbb[aa]`. */
  light?: string;
  dark?: string;
  /** Whether a color override may be translucent (`#rrggbbaa`): its default is. */
  alpha?: boolean;
  min?: number;
  max?: number;
};

function collectTokens(): Token[] {
  const css = readTheme();
  const resolveColor = colorResolver(css);
  const tokens: Token[] = [];
  const seen = new Set<string>();
  for (const { name, value } of readThemeDeclarations(css)) {
    if (name.includes("*") || fixedTokens.some((p) => p.test(name))) continue;
    if (seen.has(name)) throw new Error(`theme.css: --${name} is declared twice`);
    seen.add(name);
    const rule = tokenRules.find((r) => r.pattern.test(name));
    if (rule === undefined) throw new Error(`theme.css: --${name} matches no rule in tokenRules or fixedTokens (src/tokens.ts)`);
    const token: Token = { name, kind: rule.kind };
    if (rule.kind === "color") {
      const light = resolveColor(value, "light");
      const dark = resolveColor(value, "dark");
      token.light = toHex(light);
      token.dark = toHex(dark);
      if (light.alpha < 1 || dark.alpha < 1) token.alpha = true;
    } else {
      token.value = value;
    }
    if (rule.min !== undefined) token.min = rule.min;
    if (rule.max !== undefined) token.max = rule.max;
    tokens.push(token);
  }
  return tokens;
}

const goKinds: Record<TokenKind, string> = {
  color: "ThemeTokenColor",
  length: "ThemeTokenLength",
  number: "ThemeTokenNumber",
  "font-family": "ThemeTokenFontFamily",
  shadow: "ThemeTokenShadow",
  duration: "ThemeTokenDuration",
  easing: "ThemeTokenEasing",
};

/** A Go interpreted string literal: JSON's escapes are a subset of Go's. */
const goString = (s: string) => JSON.stringify(s);

function renderGo(tokens: Token[]): string {
  const lines = [
    "// SPDX-License-Identifier: AGPL-3.0-only",
    "",
    "// Code generated by app/ui/scripts/theme-tokens.ts from app/ui/src/theme.css and tokens.ts; DO NOT EDIT.",
    "// Regenerate with `make web-tokens-gen`.",
    "",
    "package instance",
    "",
    "// themeTokens are the tokens a server theme may override, in the order of theme.css.",
    "var themeTokens = []ThemeToken{",
  ];
  for (const t of tokens) {
    const fields = [`Name: ${goString(t.name)}`, `Kind: ${goKinds[t.kind]}`];
    if (t.light !== undefined) fields.push(`Light: ${goString(t.light)}`, `Dark: ${goString(t.dark ?? "")}`);
    if (t.alpha === true) fields.push("Alpha: true");
    if (t.value !== undefined) fields.push(`Default: ${goString(t.value)}`);
    if (t.min !== undefined) fields.push(`Min: ${t.min}`);
    if (t.max !== undefined) fields.push(`Max: ${t.max}`);
    lines.push(`\t{${fields.join(", ")}},`);
  }
  lines.push("}", "", "// themeContrastPairs are the foreground / background pairs of the color tokens and their minimum", "// contrast ratios (WCAG 2.2 AA).", "var themeContrastPairs = []ContrastPair{");
  for (const p of themeColorPairs) {
    lines.push(`\t{FG: ${goString(`color-${p.fg}`)}, BG: ${goString(`color-${p.bg}`)}, Minimum: ${minimumContrast[p.use]}},`);
  }
  lines.push("}", "");
  return lines.join("\n");
}

function renderTs(tokens: Token[]): string {
  const lines = [
    "// SPDX-License-Identifier: AGPL-3.0-only",
    "// Generated by scripts/theme-tokens.ts from theme.css and tokens.ts; do not edit. Regenerate with `make web-tokens-gen`.",
    'import type { TokenKind } from "./tokens";',
    "",
    "/** A token of theme.css that a server theme may override (ADR-0059), named without `--`. */",
    "export type ThemeToken = {",
    "  name: string;",
    "  kind: TokenKind;",
    "  /** The default of a non-color token. */",
    "  value?: string;",
    "  /** The default of a color token in each theme, as `#rrggbb[aa]`. */",
    "  light?: string;",
    "  dark?: string;",
    "  /** Whether a color override may be translucent (`#rrggbbaa`). */",
    "  alpha?: boolean;",
    "  /** The bounds of a length (rem), number, or duration (ms). */",
    "  min?: number;",
    "  max?: number;",
    "};",
    "",
    "/** The overridable tokens, in the order of theme.css. */",
    `export const themeTokens: readonly ThemeToken[] = ${JSON.stringify(tokens, null, 2)};`,
    "",
  ];
  return lines.join("\n");
}

/** The generated files by path, with their content. */
function generate(): Map<string, string> {
  const tokens = collectTokens();
  return new Map([
    [goPath, renderGo(tokens)],
    [tsPath, renderTs(tokens)],
  ]);
}

/** Problems with the committed generated files: each one that differs from what generate() writes. */
export function checkGenerated(): string[] {
  const problems: string[] = [];
  for (const [path, content] of generate()) {
    let current = "";
    try {
      current = readFileSync(path, "utf8");
    } catch {
      // Missing: reported below.
    }
    if (current !== content) problems.push(`${path.slice(root.length + 1)} is stale; run \`make web-tokens-gen\``);
  }
  return problems;
}

if (import.meta.main) {
  for (const [path, content] of generate()) writeFileSync(path, content);
}
